// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        address oldOwner = c.owner();
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(
            ok == (caller == oldOwner) && (!ok || c.owner() == newOwner),
            "transferOwnership must be callable only by the current owner and set owner to newOwner"
        );
    }
}
